/**
 * What a game's cathode.json means for its Android and iOS projects.
 *
 * The native projects are generated by Capacitor and then edited here, so
 * every value comes from cathode.json and nowhere else. Each edit replaces a
 * value rather than adding one, so applying them twice changes nothing.
 */
import type { Orientation, Project } from '@cathode/project';

/** The Capacitor release games are built with. Native projects are remade when it changes. */
export const CAPACITOR_VERSION = '8.5.3';

export type Platform = 'android' | 'ios';

/** Where each platform's project lives, inside the game's folder. */
export const NATIVE_DIR: Record<Platform, string> = { android: 'native/android', ios: 'native/ios' };

/**
 * The whole-number build version both stores need alongside "1.2.3": it must
 * go up with every upload. MAJOR.MINOR.PATCH becomes MAJOR·1,000,000 +
 * MINOR·1,000 + PATCH, so it rises whenever the version does.
 */
export function versionCode(version: string): number {
  const [major, minor, patch] = version.split('.').map(Number);
  return major * 1_000_000 + minor * 1_000 + patch;
}

/** A stand-in store ID for a game that has none yet. Fine on a test device, refused by Google Play. */
export function placeholderId(name: string): string {
  const word = name.replace(/-/g, '');
  return `com.example.${/^[a-z]/.test(word) ? word : `g${word}`}`;
}

export const isPlaceholderId = (id: string) => /^com\.example\./i.test(id);

/** capacitor.config.json: everything Capacitor needs to know, from cathode.json. */
export function capacitorConfig(project: Project, id: string): object {
  return {
    appId: id,
    appName: project.title,
    webDir: 'dist',
    // Behind the game before it draws, and around it on a screen of another shape.
    backgroundColor: '#000000',
    android: { path: NATIVE_DIR.android },
    ios: { path: NATIVE_DIR.ios },
    plugins: {
      // A game wants the whole screen: no status bar, no navigation bar. They
      // come back for a moment with a swipe from the edge.
      SystemBars: { hidden: true, style: 'DARK', insetsHandling: 'css' },
    },
  };
}

const escapeXml = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

/** Android string resources also treat quotes, and a leading @ or ?, as syntax. */
const androidText = (s: string) => escapeXml(s).replace(/(["'])/g, '\\$1').replace(/^([@?])/, '\\$1');

/** Replace the one match of `pattern`, or fail loudly: a silent miss would ship the template's value. */
function replaceOne(text: string, pattern: RegExp, replacement: string, what: string): string {
  if (!pattern.test(text)) throw new Error(`could not find ${what} to set in the generated project`);
  return text.replace(pattern, replacement);
}

const SIGNING_MARK = '// cathode: release signing';

/**
 * Release builds are signed with the upload key named by environment
 * variables, so no password is ever written into the project.
 */
const SIGNING = `
${SIGNING_MARK} -- signs release builds with the upload key the
// CATHODE_KEYSTORE* environment variables name. See docs/shipping.md.
if (System.getenv('CATHODE_KEYSTORE')) {
    android {
        signingConfigs {
            release {
                storeFile file(System.getenv('CATHODE_KEYSTORE'))
                storePassword System.getenv('CATHODE_KEYSTORE_PASSWORD')
                keyAlias System.getenv('CATHODE_KEY_ALIAS')
                keyPassword System.getenv('CATHODE_KEY_PASSWORD') ?: System.getenv('CATHODE_KEYSTORE_PASSWORD')
            }
        }
        buildTypes.release.signingConfig signingConfigs.release
    }
}
`;

/** android/app/build.gradle: store ID, version, and release signing. */
export function androidAppGradle(text: string, project: Project, id: string): string {
  let out = replaceOne(text, /applicationId\s+"[^"]*"/, `applicationId "${id}"`, 'applicationId');
  out = replaceOne(out, /versionCode\s+\d+/, `versionCode ${versionCode(project.version)}`, 'versionCode');
  out = replaceOne(out, /versionName\s+"[^"]*"/, `versionName "${project.version}"`, 'versionName');
  if (!out.includes(SIGNING_MARK)) out = `${out.trimEnd()}\n${SIGNING}`;
  return out;
}

/** android/app/src/main/res/values/strings.xml: the name under the icon. */
export function androidStrings(text: string, project: Project): string {
  const title = androidText(project.title);
  let out = replaceOne(text, /(<string name="app_name">)[^<]*(<\/string>)/, `$1${title}$2`, 'app_name');
  out = replaceOne(out, /(<string name="title_activity_main">)[^<]*(<\/string>)/, `$1${title}$2`, 'title_activity_main');
  return out;
}

const ANDROID_ORIENTATION: Record<Orientation, string | null> = {
  landscape: 'sensorLandscape', // either way up
  portrait: 'sensorPortrait',
  any: null,
};

/** AndroidManifest.xml: which ways the phone can be held. */
export function androidManifest(text: string, project: Project): string {
  const want = ANDROID_ORIENTATION[project.orientation ?? 'landscape'];
  const withoutOrientation = text.replace(/\s+android:screenOrientation="[^"]*"/, '');
  if (!want) return withoutOrientation;
  return replaceOne(
    withoutOrientation,
    /(<activity\b)/,
    `$1\n            android:screenOrientation="${want}"`,
    'the main activity',
  );
}

/** Set one `<item>` of a style in styles.xml, replacing any it already has. */
function styleItem(text: string, style: string, name: string, value: string): string {
  const block = new RegExp(`(<style name="${style.replace(/\./g, '\\.')}"[^>]*>)([\\s\\S]*?)(\\s*</style>)`);
  if (!block.test(text)) throw new Error(`could not find the ${style} style in the generated project`);
  return text.replace(block, (_, open: string, body: string, close: string) => {
    const others = body.replace(new RegExp(`\\s*<item name="${name}">[^<]*</item>`), '');
    return `${open}${others}\n        <item name="${name}">${value}</item>${close}`;
  });
}

/** styles.xml: black behind the launch screen and the game, never a white flash. */
export function androidStyles(text: string): string {
  const out = styleItem(text, 'AppTheme.NoActionBarLaunch', 'windowSplashScreenBackground', '#000000');
  return styleItem(out, 'AppTheme.NoActionBar', 'android:windowBackground', '@android:color/black');
}

/** values/ic_launcher_background.xml: the colour behind an adaptive icon. */
export function androidIconBackground(text: string, colour: string): string {
  return replaceOne(text, /(<color name="ic_launcher_background">)[^<]*(<\/color>)/, `$1${colour}$2`, 'ic_launcher_background');
}

/** Set a key in a property list, replacing its value or adding it. */
export function plistSet(text: string, key: string, valueXml: string): string {
  const existing = new RegExp(`(<key>${key}</key>\\s*)(<string>[^<]*</string>|<true/>|<false/>|<array>[\\s\\S]*?</array>)`);
  if (existing.test(text)) return text.replace(existing, `$1${valueXml}`);
  return replaceOne(text, /(\n?)(<\/dict>\s*<\/plist>\s*)$/, `\n\t<key>${key}</key>\n\t${valueXml}$1$2`, 'the end of Info.plist');
}

const IOS_ORIENTATIONS: Record<Orientation, string[]> = {
  landscape: ['UIInterfaceOrientationLandscapeLeft', 'UIInterfaceOrientationLandscapeRight'],
  portrait: ['UIInterfaceOrientationPortrait'],
  any: ['UIInterfaceOrientationPortrait', 'UIInterfaceOrientationLandscapeLeft', 'UIInterfaceOrientationLandscapeRight'],
};

const plistArray = (items: string[]) =>
  `<array>\n${items.map((i) => `\t\t<string>${i}</string>`).join('\n')}\n\t</array>`;

/** Info.plist: the name under the icon, orientation, and no status bar. */
export function iosInfoPlist(text: string, project: Project): string {
  let out = plistSet(text, 'CFBundleDisplayName', `<string>${escapeXml(project.title)}</string>`);
  out = plistSet(out, 'UISupportedInterfaceOrientations', plistArray(IOS_ORIENTATIONS[project.orientation ?? 'landscape']));
  // iPadOS 26 deprecates locking an iPad app's orientation and expects every
  // app to resize. The engine fits any shape, so iPads get all four.
  out = plistSet(out, 'UISupportedInterfaceOrientations~ipad', plistArray([
    'UIInterfaceOrientationPortrait', 'UIInterfaceOrientationPortraitUpsideDown',
    'UIInterfaceOrientationLandscapeLeft', 'UIInterfaceOrientationLandscapeRight',
  ]));
  out = plistSet(out, 'UIStatusBarHidden', '<true/>');
  return out;
}

/** project.pbxproj: store ID and version, in every build configuration. */
export function iosProject(text: string, project: Project, id: string): string {
  const every = (input: string, setting: string, value: string) => {
    const pattern = new RegExp(`(${setting} = )[^;]*;`, 'g');
    if (!pattern.test(input)) throw new Error(`could not find ${setting} to set in the generated project`);
    return input.replace(pattern, `$1${value};`);
  };
  let out = every(text, 'PRODUCT_BUNDLE_IDENTIFIER', id);
  out = every(out, 'MARKETING_VERSION', project.version);
  out = every(out, 'CURRENT_PROJECT_VERSION', String(versionCode(project.version)));
  return out;
}
